class Faq {
  constructor(tanya, jawab) {
    this.el = document.createElement("div");
    this.el.classList.add("faq");
    const tombol = document.createElement("button");
    tombol.textContent = tanya;
    const isi = document.createElement("p");
    isi.textContent = jawab;
    tombol.addEventListener("click", () => this.toggle());
    this.el.append(tombol, isi);
  }
  toggle() {
    return this.el.classList.toggle("buka");
  }
}
const wadah = document.querySelector("#daftar-faq");
const semua = [
  new Faq("Apakah gratis?", "Ya, semua kelas gratis."),
  new Faq("Perlu instal aplikasi?", "Tidak, cukup browser."),
];
semua.forEach((f) => wadah.append(f.el));
semua[1].el.querySelector("button").click();
console.log(wadah.querySelectorAll(".buka").length);
console.log(semua[1].toggle());

